import os
# Keys falsas: solo construimos los objetos, no se llama a ninguna API
for var in ["OPENAI_API_KEY", "ANTHROPIC_API_KEY", "GOOGLE_API_KEY"]:
    os.environ.setdefault(var, "falsa")

from langchain.chat_models import init_chat_model

for name in ["openai:gpt-5-nano", "anthropic:claude-sonnet-4-6",
             "google_genai:gemini-2.5-flash", "openai:gpt-audio"]:
    p = init_chat_model(name).profile
    if not p:
        print(f"{name:30} sin profile: revisa la doc del proveedor")
    else:
        print(f"{name:30} image={p['image_inputs']} audio={p['audio_inputs']}")
